sys_script_include.script:
var FHIRPatientContextService = Class.create();
FHIRPatientContextService.prototype = {

    initialize: function() {
        this.USER_ROLE = 'x_1886160_fhir_p_0.user';
        this.AUDIT_TABLE = 'x_1886160_fhir_p_0_access_audit';
        this.CONN_TABLE = 'x_1886160_fhir_p_0_fhir_connection';
    },

    run: function(connectionSysId, mrn, system) {
        var result = {
            outcome: 'error',
            message: '',
            patientId: null,
            candidateIds: [],
            context: null
        };

        if (!gs.hasRole(this.USER_ROLE)) {
            result.outcome = 'forbidden';
            result.message = 'Access requires role ' + this.USER_ROLE + '.';
            this._audit(connectionSysId, null, result.outcome, result.message, null);
            return result;
        }

        connectionSysId = this._pickConnection(connectionSysId);
        if (!connectionSysId) {
            result.outcome = 'error';
            result.message = 'No active FHIR connection is configured.';
            this._audit(null, null, result.outcome, result.message, null);
            return result;
        }

        var resolver = new x_1886160_fhir_p_0.FHIRPatientResolver();
        var r = resolver.resolve(connectionSysId, mrn, system);

        if (r.outcome !== 'found') {
            result.outcome = r.outcome;
            result.message = r.message;
            result.candidateIds = r.candidateIds || [];
            this._audit(connectionSysId, r.patientId, result.outcome, result.message, null);
            return result;
        }

        result.patientId = r.patientId;

        var svc = new x_1886160_fhir_p_0.FHIREnrichmentService();
        var ctx = svc.getEnrichment(connectionSysId, r.patientId);

        result.context = ctx;
        result.outcome = 'ok';
        result.message = 'Patient context assembled for Patient/' + r.patientId + '.';
        this._audit(connectionSysId, r.patientId, result.outcome, result.message, ctx);
        return result;
    },

    _pickConnection: function(connectionSysId) {
        if (connectionSysId) {
            return connectionSysId;
        }
        var gr = new GlideRecord(this.CONN_TABLE);
        gr.addQuery('active', true);
        gr.orderBy('sys_created_on');
        gr.setLimit(1);
        gr.query();
        if (gr.next()) {
            return gr.getUniqueValue();
        }
        return null;
    },

    _audit: function(connectionSysId, patientId, outcome, message, ctx) {
        try {
            var gr = new GlideRecord(this.AUDIT_TABLE);
            gr.initialize();
            gr.setValue('accessed_by', gs.getUserID());
            if (connectionSysId) {
                gr.setValue('connection', connectionSysId);
            }
            gr.setValue('patient_id', patientId || '');
            gr.setValue('outcome', outcome);
            gr.setValue('message', ('' + (message || '')).substr(0, 1000));
            if (ctx && ctx.sections) {
                gr.setValue('conditions_count', (ctx.sections.conditions || []).length);
                gr.setValue('encounters_count', (ctx.sections.encounters || []).length);
                gr.setValue('labs_count', (ctx.sections.labs || []).length);
            }
            gr.insert();
        } catch (e) {
            gs.error('FHIRPatientContextService audit write failed: ' + e.message);
        }
    },

    type: 'FHIRPatientContextService'
};
